   "原题": "20.（12分）【问题背景】赵爽弦图是中国古代数学家赵爽为证明勾股定理设计的几何图形．郑州市中原区某中学的数学实验室社团在“数学文化节”上展示了这个经典图形：四个直角三角形较大的直角边长都为a，较小的直角边长都为b，斜边长都为c，大正方形的面积可以表示为c²，也可以表示为4×1/2ab+(a−b)²，由此推导出勾股定理：如果直角三角形两条直角边长为a，b，斜边长为c，则a²+b²=c²．\n(1)【探索求证】数学实验室里，学生用硬纸板拼出如图②的模型：Rt△ADE与Rt△EBC按如图所示位置放置，其中∠A=∠B=∠DEC=90°，请你利用图②推导勾股定理．\n(2)【问题解决】中原区某学校在东西走向的操场北侧有一个花园C，操场边原有两个取水点A、B（A，B，H在同一直线上），其中AB=AC，因操场改造，CA路封闭，学校决定在操场边新建取水点H并修新路CH，且CH⊥AB．测得CH=24米，HB=18米，求新路CH比原路CA少多少米？\n(3)【延伸扩展】在问题解决中若AB≠AC时，CH⊥AB，AC=15米，BC=18米，AB=21米，求AH的长度？\n（图②：A、E、B 在同一直线上，AD=b，AE=a，EB=b，BC=a，DE=CE=c。）",
