   "原题": "19.（10分）项目式学习\n【项目背景】某校八年级数学兴趣小组成员自主开展数学微项目研究，结合本阶段学习内容，他们对「勾股树」（毕达哥拉斯树）产生了浓厚兴趣。\n【素材一】毕达哥拉斯树，也叫「勾股树」，是由毕达哥拉斯根据勾股定理而创造的一种分形树。如图所示，以直角三角形的三条边为边长作正方形，然后由两个小正方形向外分别作直角三角形，再分别以所得到的直角三角形的直角边为边长作正方形，如此重复数次后的形状好似一棵树，所以被称为毕达哥拉斯树。\n【素材二】经过小组讨论，制定了如下规则：①画出不同类型三角形形成的树形图；②所画的基础三角形周长为 8cm，其中一条边长固定为 2cm。根据规则，三位同学分别画出下面不同类型的树形图并进行探究。\n（图意：图1 锐角三角形 ABC，正方形 S1 建在 BC 上，S2 建在 AB 上，S3 建在 AC 上；图2 直角三角形 DEF，∠EFD=90°，S1 建在 EF 上，S2 建在 DF 上，S3 建在斜边 DE 上；图3 钝角三角形 GHI，∠HIG=120°，S1 建在 HI 上，S2 建在 GI 上，S3 建在 GH 上。）\n【解决问题】(1) 图1，小明画出了锐角三角形 ABC，AB=AC，BC=2cm，计算 S1/S2 的值，并写出过程。",
