   "原题": "19.（11分）阅读材料：若想化简√(m±2√n)，只要我们找到两个正数a，b，使a+b=m，ab=n，即(√a)²+(√b)²=m，√a·√b=√n，那么便有：√(m±2√n)=√((√a±√b)²)=√a±√b(a>b).\n例：化简√(7+4√3).\n解：首先把√(7+4√3)化为√(7+2√12)，这里m=7，n=12，由于4+3=7，4×3=12.\n即(√4)²+(√3)²=7，√4×√3=√12.　∴√(7+4√3)=√(7+2√12)=√((√4+√3)²)=2+√3.\n请你仿照阅读材料的方法解决下列问题：\n（1）填空：√(4−2√3)=______，√(5−2√6)=______；\n（2）化简：√(19−4√15)；写出计算过程\n（3）化简：√(3−2√2)+√(5−2√6)+√(7−2√12)+…+√(2n+1−2√(nn+1)). n为正整数\n（原卷最后一项根号内印作“nn+1”，应为 n(n+1)。）\n（本条收录第(3)问；第(1)(2)问正确。）",
