   "原题": "18.（8分）嘉嘉根据学习「数与式」积累的活动经验，想通过「特殊到一般」的方法探究二次根式的运算规律。下面是嘉嘉的探究过程：\n等式① √(1+1/3)=2√(1/3)\n等式② √(2+1/4)=3√(1/4)\n等式③ √(3+1/5)=4√(1/5)\n等式④ ________\n(1)【特例探究】将题目中的横线处补充完整；\n(2)【归纳猜想】若 n 为正整数，用含 n 的代数式表示上述运算规律，并证明此规律成立；\n(3)【应用规律】嘉嘉写出一个等式 √(a+1/b)=c√(1/b)（a、b、c 均为正整数），若该等式符合上述规律，则 √(a²+b²−2c²)=________。",
