   "原题": "8.（3分）周末，小张、小李两人相约沿鲲鹏径同一路线从 A 处骑行至 B 处，小张、小李分别以不同的速度匀速骑行，小李比小张早出发 5 分钟。小李骑行 25 分钟后，小张以原速的 8/5 继续骑行，经过一段时间，小张先到达 B 地，小李一直保持原速前往 B 地。在此过程中，小张、小李两人相距的路程 y（单位：米）与小李骑行的时间 x（单位：分钟）之间的关系如图所示。有以下几个结论：①小李的速度为 300 米/分钟；②小张出发 50 分钟时追上小李；③A、B 两地相距 20000 米；④小李比小张晚 25/3 分钟到达 B 地。其中正确的是（ ）\nA. ①②　B. ①④　C. ①②③　D. ①③④\n（图意：y–x 折线，关键点约 (0,0)、(5,1500)、(25,2500)，随后降到 y=0，再升至 x=75 处峰值后降回 0。）",
   "正确答案": "B（①④）\n①：0≤x≤5 仅小李骑行，y=v_李·x；由图 (5,1500) 得 v_李=300。正确。\n5≤x≤25：Δy=1000/20=50=v_李−v_张 ⇒ v_张=250。\nx≥25：小张改速 8/5×250=400；相对速度 300−400=−100，从 y=2500 追上需 25 分钟，于 x=50 相遇。此时小张已出发 45 分钟，故②「出发 50 分钟时追上」错误。\n若图中第二峰在 x=75 为小张到达 B：小张路程=250×20+400×50=25000，故③「20000 米」错误。\n小张到 B 后，相距=小李剩余；峰值 2500，小李再骑 2500/300=25/3 分钟到 B，故④正确。",
