   "原题": "19. 我们定义一个新的概念：“平衡数对”．对于给定的两个数a和b，当且仅当满足等式3a+2b=5(a−b)+10时，我们称数对(a，b)为“平衡数对”．并且，若存在另一个数对(c，d)，使得c=a+b，d=a−b，我们称数对(c，d)为(a，b)的“衍生数对”．\n(1)判断(5，2)是否为“平衡数对”，并说明理由．\n(2)已知数对(x，3)是“平衡数对”，求出该数对的“衍生数对”．\n(3)若数对(m，n)是“平衡数对”，且其“衍生数对”(p，q)满足条件：2p+3q=15，求出m和n的值．",
